<?= $this->section('scripts') ?><script>
$(function(){
 $('#patient-time').attr({type:'text',placeholder:'hh:mm AM/PM',inputmode:'text',autocomplete:'off'});
 $('.reschedule-appointment').each(function(){const button=$(this);const raw=button.attr('data-time');const formatted=window.rootinsFormatTime(raw);if(formatted){button.attr('data-time',formatted);}});
 $('.table-responsive table tbody tr').each(function(){const cell=$(this).find('td').eq(2);if(!cell.length)return;const text=cell.text();const match=text.match(/(\d{1,2}:\d{2}(?::\d{2})?)\s*$/);if(!match)return;const formatted=window.rootinsFormatTime(match[1]);if(!formatted)return;cell.contents().filter(function(){return this.nodeType===3;}).last().each(function(){this.nodeValue=this.nodeValue.replace(match[1],formatted);});});
 const esc=value=>$('<div>').text(value==null?'':value).html();
 const patientOrders = <?= json_encode(array_map(static function (array $order) use ($orderItems): array { return ['id' => (int) $order['id'], 'order_number' => (string) $order['order_number'], 'prescription_number' => (string) $order['prescription_number'], 'status' => (string) $order['status'], 'payment_status' => (string) $order['payment_status'], 'delivery_status' => (string) $order['delivery_status'], 'provider' => (string) ($order['payment_provider'] ?? ''), 'tracking' => (string) ($order['tracking_reference'] ?? ''), 'created' => (string) ($order['created_at'] ?? ''), 'updated' => (string) ($order['updated_at'] ?? ''), 'items' => array_map(static fn (array $item): array => ['name' => (string) ($item['medicine_name'] ?? ''), 'quantity' => (int) ($item['quantity'] ?? 0)], $orderItems[(int) $order['id']] ?? [])]; }, $orders ?? []), JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;
 $('.patient-order-detail').on('click',function(){const order=patientOrders.find(item=>item.id===Number($(this).data('order-id')));if(!order)return;const items=order.items.map(item=>'<tr><td>'+esc(item.name)+'</td><td>'+esc(item.quantity)+'</td></tr>').join('');$('#patient-order-detail-body').html('<p><strong>'+esc(order.order_number)+'</strong><br>Prescription: '+esc(order.prescription_number)+'</p><div class="mb-3"><span class="badge badge-light">Order: '+esc(order.status)+'</span> <span class="badge badge-light">Payment: '+esc(order.payment_status)+'</span> <span class="badge badge-light">Delivery: '+esc(order.delivery_status)+'</span></div><p class="small">Provider: '+esc(order.provider||'Not recorded')+'<br>Tracking: '+esc(order.tracking||'Not recorded')+'<br>Created: '+esc(order.created)+'<br>Updated: '+esc(order.updated)+'</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Medicine</th><th>Quantity</th></tr></thead><tbody>'+items+'</tbody></table></div>');});
 bindCountryCodeToggles('#profile-form');
 $('.save-profile').on('click',function(){clearFormErrors();ajaxRequest({url:'<?= base_url('patient/profile') ?>',data:$('#profile-form').serialize(),success:function(r){if(r.status){showSuccess(r.msg);}else{showError(r.msg);bindFormError('#profile-form',r.errors);}}});});
 $('.book-appointment').on('click',function(){ajaxRequest({url:'<?= base_url('patient/appointments/book') ?>',data:$('#booking-form').serialize(),success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else{showError(r.msg);}}});});
 $('.reschedule-appointment').on('click',function(){const button=$(this);const date=window.prompt('New appointment date (YYYY-MM-DD):',button.data('date'));if(date===null)return;const time=window.prompt('New appointment time (HH:MM):',button.data('time'));if(time===null)return;ajaxRequest({url:'<?= base_url('patient/appointments/reschedule') ?>/'+button.data('id'),data:{appointment_date:date,appointment_time:time},success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else{showError(r.msg);}}});});
 $('.cancel-appointment').on('click',function(){const id=$(this).data('id');ajaxRequest({url:'<?= base_url('patient/appointments/cancel') ?>/'+id,data:{cancellation_reason:'Cancelled by patient'},success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else{showError(r.msg);}}});});
 $('.upload-document').on('click',function(){const form=new FormData($('#document-form')[0]);ajaxRequest({url:'<?= base_url('patient/documents/upload') ?>',data:form,processData:false,contentType:false,success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else{showError(r.msg);}}});});
});
</script><?= $this->endSection() ?>
